// EXT03 «Энциклопедия функций: ссылки, операторы, числа и логика» — дополнительный модуль курса «Бухгалтерия» (сверх ТЗ).
// 14 уроков: О1, О2, О4 и Ф01–Ф11 из docs/courses/accounting/functions-audit.md (раздел 6).
// Данные вымышленные: листы «Платежи», «Сотрудники», «Сверка» практикума и небольшие свои таблицы.
// Все числа в примерах, шагах и вопросах проверены программно на Python (scripts/accounting/verify_ext03.py), НЕ в Excel:
// Excel у автора курса нет. Заметка исследования — docs/courses/accounting/research/EXT03.md.
// Имена функций — по разделу «Русские имена функций» в docs/courses/accounting/excel-compatibility.md.
import { p, qq, qmulti, qtf, qfill, qnum, qtable, qgap, qxl, hard, withFigures } from '../lessonAuthoring'
import type { LessonFigure } from '../lessonAuthoring'
import { excelSheet, formulaFig } from './accFigures'
import type { FormulaPart } from './accFigures'
import { trainerFig } from '../../lib/excelLab/figures'
import type { TrainerSpec, XlSheet } from '../../lib/excelLab/spec'
import { EXT03_TRAINERS } from './trainers/ext03'
import type { AccModule, AccLesson, AccSource } from './types'
import type { HomeworkQuizQuestion, HomeworkTeacherTask } from '../lessonContent'

/** sample — мини-лист примера; partRefs/stepRefs — что подсвечивать (по номеру части/шага). */
type Fig = {
  title: string; parts: FormulaPart[]; steps: Array<[string, string]>; cap: string; note?: string
  sample?: XlSheet | XlSheet[]; partRefs?: Array<string[] | undefined>; stepRefs?: Array<string[] | undefined>
}
/** Тренажёр урока: набор, формулировка вопроса в квизе и разбор. */
type Trainer = { spec: TrainerSpec; prompt: string; explanation: string }
interface Spec {
  n: number
  title: string
  topics: string[]
  minutes: number
  practice: string
  queries: string[]
  sources: string[]
  open?: string[]
  /** Вопрос из работы. */
  task: string
  /** Зачем — одной фразой, бухгалтерский пример. */
  zachem: string
  need: string
  /** Синтаксис и аргументы: каждый аргумент — отдельная строка. */
  args: string[]
  /** Формулы: [русская, английская, комментарий]. */
  forms: Array<[string, string, string]>
  figs: Fig[]
  trainer?: Trainer
  sheet: { title: string; rows: string[][]; formula: string; sel: [number, number]; note?: string; cap: string }
  exText: string[]
  steps: string[]
  logic: string
  change: string
  ba: string
  work: string
  errs: string[]
  hint: string
  check: string
  compat: string
  choose?: string
  quiz: HomeworkQuizQuestion[]
  hard: HomeworkTeacherTask
  msLine: string
}

const L = (s: Spec): AccLesson => {
  const nn = String(s.n).padStart(2, '0')
  const paragraphs = [
    p('task', `**Вопрос из работы.** ${s.task}\n**Зачем нужна функция.** ${s.zachem}`),
    p('need', `**Что нужно.** ${s.need}`),
    p('args', `**Синтаксис и аргументы.**\n${s.args.map(a => `— ${a}`).join('\n')}`),
    p('formula', `**Формулы.**\n${s.forms.map(([ru, en, c]) => `— \`${ru}\` — ${c}. Англ.: \`${en}\``).join('\n')}`),
    p('ex', `**Пример таблицы (текстом).**\n${s.exText.map(t => `— ${t}`).join('\n')}`),
    p('steps', `**Шаги.**\n${s.steps.map((t, i) => `**Шаг ${i + 1}.** ${t}`).join('\n')}`),
    p('why', `**Почему работает.** ${s.logic}`),
    p('change', `**Поменяйте и проверьте.** ${s.trainer ? 'В тренажёре выше или в своём Excel: ' : ''}${s.change}`),
    p('ba', `**Было → стало.** ${s.ba}`),
    p('work', `**В бухгалтерской работе.** ${s.work}`),
    p('errs', `**Типичные ошибки.**\n${s.errs.map(e => `— ${e}`).join('\n')}`),
    p('hint', `**Подсказка.** ${s.hint}`),
    p('check', `**Проверка себя.** ${s.check}`),
    p('compat', `**В какой версии Excel.** ${s.compat}`),
    ...(s.choose ? [p('choose', `**Какой способ выбрать.** ${s.choose}`)] : []),
    p('src', `**Источники:** ${s.msLine} Проверено 27.11.2026: страницы Microsoft открыты, числа примеров проверены программно (Python), не в Excel.`),
  ]
  const figures: LessonFigure[] = [
    ...s.figs.map(f => ({
      after: 'formula', caption: f.cap,
      src: formulaFig(
        f.title,
        f.parts.map((pt, i) => (f.partRefs?.[i] ? { ...pt, refs: f.partRefs[i] } : pt)),
        f.steps.map((st, i) => (f.stepRefs?.[i] ? [st[0], st[1], f.stepRefs[i]!] as [string, string, string[]] : st)),
        { ...(f.note ? { note: f.note } : {}), ...(f.sample ? { sample: f.sample } : {}) },
      ),
    })),
    { after: 'ex', caption: s.sheet.cap, src: excelSheet(s.sheet.title, s.sheet.rows, { formula: s.sheet.formula, selected: s.sheet.sel, note: s.sheet.note }) },
    ...(s.trainer ? [{ after: 'errs', caption: 'Тренажёр: поменяйте значения и посмотрите, как меняется результат', src: trainerFig(s.trainer.spec) }] : []),
  ]
  const quiz = s.trainer ? [...s.quiz, qxl(`acc-x03-${nn}-q${s.quiz.length + 1}`, s.trainer.prompt, s.trainer.spec, s.trainer.explanation)] : s.quiz
  const withF = withFigures({ [s.title]: { paragraphs, quiz, hardTask: s.hard } }, { [s.title]: figures })[s.title]
  return {
    key: `x03-${nn}`,
    title: s.title,
    topics: s.topics,
    origin: [],
    minutes: s.minutes,
    practice: s.practice,
    software: 'Excel (версия учащейся не подтверждена: у каждой функции дана строка совместимости и замена для старых версий)',
    applies: 'Не зависит от года; проверено по документации Microsoft 27.11.2026',
    sources: s.sources,
    queries: s.queries,
    open: s.open,
    content: withF,
  }
}


