      sample: S_BUY, partRefs: [undefined, ['B2:B4'], undefined, ['C2:C4']], stepRefs: [['B2', 'C2'], ['B3', 'C3'], ['B4', 'C4'], ['B2:C4']],
      parts: [{ text: '=СУММПРОИЗВ(' }, { text: 'B2:B4', label: 'Количество: 10; 4; 25' }, { text: ';' }, { text: 'C2:C4', label: 'Цена: 150; 2 500; 80' }, { text: ')' }],
      steps: [['10 × 150', '1 500'], ['4 × 2 500', '10 000'], ['25 × 80', '2 000'], ['1 500 + 10 000 + 2 000', '13 500']],
