      parts: [{ text: '=СУММЕСЛИ(' }, { text: 'B2:B7', label: 'Где искать условие: организации' }, { text: ';' }, { text: '"Альфа"', label: 'Что ищем (текст в кавычках)' }, { text: ';' }, { text: 'D2:D7', label: 'Что складываем: суммы платежей' }, { text: ')' }],
      steps: [['строки с «Альфа»: P01, P03, P06', '12 000; 4 000; 2 000'], ['12 000 + 4 000 + 2 000', '18 000']],
